def _op_diff(before, after, limit=24):
    lines = list(difflib.unified_diff(
        before.splitlines(), after.splitlines(), fromfile="before", tofile="after", lineterm="", n=2,
    ))
    if len(lines) > limit: lines = [*lines[:limit], "... diff truncated ..."]
