def _format_batch_details(details):
    lines = []
    for item in details:
        cell = f" id={item['cell_id']}" if item.get("cell_id") else ""
        lines.append(f"- {item['op']}: {item['path']}{cell}")
        if item.get("diff"):
            lines.extend(f"    {line}" for line in item["diff"].splitlines())
    return "\n".join(lines)

